pub fn update_fee(
    program_id: &Pubkey,
    accounts: &[AccountInfo],
    data: &[u8],
) -> ProgramResult {
    if accounts.len() < 2 {
        return Err(ProgramError::NotEnoughAccountKeys);
    }

    let marketplace = &accounts[0];
    let admin = &accounts[1];

    if !admin.is_signer {
        return Err(ProgramError::MissingRequiredSignature);
    }
    if !marketplace.is_writable || !admin.is_writable {
        return Err(ProgramError::InvalidAccountData);
    }
    if marketplace.owner != program_id {
        return Err(ProgramError::IncorrectProgramId);
    }

    // Args
    let mut remaining = data;
    if remaining.len() < 2 {
        return Err(ProgramError::InvalidInstructionData);
    }
    let (arg_bytes, rest) = remaining.split_at(2);
    remaining = rest;
    let new_fee_bps: u16 = u16::from_le_bytes(
        arg_bytes.try_into().map_err(|_| ProgramError::InvalidInstructionData)?
    );
    if !remaining.is_empty() {
        return Err(ProgramError::InvalidInstructionData);
    }

    let (expected_key, _bump_marketplace) = Pubkey::find_program_address(&[b"marketplace"], program_id);
    if expected_key != *marketplace.key {
        return Err(ProgramError::InvalidSeeds);
    }
    let marketplace_account = marketplace;
    let mut marketplace = Marketplace::read(&marketplace_account.data.borrow())?;
    if !(new_fee_bps <= 10000) {
        return Err(MarketplaceError::InvalidFeeBps.into());
    }
    if !(marketplace.admin == *admin.key) {
        return Err(MarketplaceError::Unauthorized.into());
    }
    marketplace.fee_bps = new_fee_bps;
    Marketplace::write(&mut marketplace_account.data.borrow_mut(), &marketplace)?;
    Ok(())

}

